import{z as B,x as p,o as E,c as A,q as i,j as r,D as e,d as o,s,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"合并与拆分","description":"","frontmatter":{"title":"合并与拆分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coalescing-splitting.md","filePath":"cs/coalescing-splitting.md","lastUpdated":1791063341000}'),d={name:"cs/coalescing-splitting.md"};function c(g,a,m,h,C,D){const l=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=i('<h1 id="合并与拆分" tabindex="-1">合并与拆分 <a class="header-anchor" href="#合并与拆分" aria-label="Permalink to &quot;合并与拆分&quot;">​</a></h1><div class="epigraph"><p>合并把拷贝两端收成同一颜色，删 `mov`；拆分把长区间切开，降低度数、给调度和调用点喘息。二者都改冲突图，而不是改源程序。</p><footer>—— 据 Chaitin 合并；George and Appel, Iterated Register Coalescing, 1996；Cooper 等 live range splitting 整理</footer></div><p>上一课<a href="/cs/chaitin-briggs">Chaitin–Briggs</a> 的图上来自 SSA 析构的大量拷贝。缺口是<strong>合并</strong>（coalescing）与<strong>拆分</strong>（splitting）。保守合并：不增加 \\(deg\\ge K\\) 的风险。激进合并再拆开。本课钉权衡，不写表调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>φ 析构与参数传递产生 <code>mov</code>。若两端无冲突，应收成同一虚名。过度合并拉长区间，度数升高，反而 spill。拆分：在循环外、调用点切开，插入新 <code>mov</code>，换更可着色的图。缺口是<strong>何时并、何时拆</strong>，不是简化栈。<span class="marginnote">直觉类比：合并像给两位同事拼工位——省一间办公室（少一条 <code>mov</code>），但两份东西挤进来，桌面（寄存器压力）更容易爆；拆分像让长住客中途换房，把一段超长的占用切成几段，给调度留喘息。</span></p><p>George–Appel：在简化过程中迭代合并。</p><h3 id="合并不是-gvn" tabindex="-1">合并不是 GVN <a class="header-anchor" href="#合并不是-gvn" aria-label="Permalink to &quot;合并不是 GVN&quot;">​</a></h3><p>GVN 删的是计算；合并删的是寄存器传送。值已相同，只是名不同。</p><p><span class="marginnote">George–Appel 1996。Hack 等 SSA 上合并。本课与线性扫描的区间拆分对照：同一思想，表示不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保守：Briggs/George 准则。若拷贝在循环外、两端冲突则放弃或先拆。拆分点：循环边界、call、高压力块。<span class="marginnote">数字实例：目标机器有 8 个可用寄存器（\\(K=8\\)）。某变量的区间若与 8 个以上别的活跃区间相交，它就「不可着色」，要溢出到内存；拆开成两段后每段邻居变少，可能就回到可着色一侧——这就是拆分泄压的直觉。</span></p>',11)),(E(),r(n,null,{default:e(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOV%5B%22%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20COA%5B%22%E5%90%88%E5%B9%B6%22%5D%0A%20%20LIVE%5B%22%E9%95%BF%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SPL%5B%22%E6%8B%86%E5%88%86%22%5D%0A%20%20COA%20--%3E%20IG%5B%22%E6%9B%B4%E6%96%B0%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20SPL%20--%3E%20IG%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与重物化：常数拆分后可 remat 代替传送。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"SSA 上合并要保持常规形式。析构后再合并更简单。不要合并跨越不同寄存器类（int/float）。",-1)),(E(),r(n,null,{default:e(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOV%5B%22%E5%8F%91%E7%8E%B0%E4%B8%80%E6%9D%A1%E5%8F%AF%E6%B6%88%E7%9A%84%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20CON%7B%22%E5%90%88%E5%B9%B6%E5%90%8E%E4%B8%A4%E7%AB%AF%E9%82%BB%E6%8E%A5%E7%82%B9%E6%98%AF%E5%90%A6%E4%BB%8D%E9%83%BD%E5%B0%8F%E4%BA%8E%20K%EF%BC%9F%22%7D%0A%20%20CON%20--%3E%7C%22%E6%98%AF%22%7C%20SAFE%5B%22%E4%BF%9D%E5%AE%88%E5%90%88%E5%B9%B6%EF%BC%9A%E5%88%A0%20mov%EF%BC%8C%E4%B8%8D%E5%88%B6%E9%80%A0%E9%AB%98%E5%8D%B1%E8%8A%82%E7%82%B9%22%5D%0A%20%20CON%20--%3E%7C%22%E5%90%A6%22%7C%20RISK%5B%22%E7%A1%AC%E5%B9%B6%E4%BC%9A%E6%8A%8A%E9%AB%98%E5%BA%A6%E6%95%B0%E8%8A%82%E7%82%B9%E6%8E%A8%E5%90%91%20spill%22%5D%0A%20%20RISK%20--%3E%20SPLIT%5B%22%E6%94%B9%E8%B5%B0%E6%8B%86%E5%88%86%EF%BC%9A%E5%88%87%E5%BC%80%E9%95%BF%E5%8C%BA%E9%97%B4%E9%99%8D%E4%BD%8E%E5%BA%A6%E6%95%B0%22%5D%0A%20%20SAFE%20--%3E%20IG%5B%22%E6%9B%B4%E6%96%B0%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20SPLIT%20--%3E%20IG%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">这张图回答「什么时候敢并、什么时候只能拆」。常见误区：以为合并总是赚——合并把两个活跃区间并成一条更长的，同时相交的邻居变多、度数升高，超过可用寄存器数就溢出，反而多出成堆 load/store。工程上的答案是 George–Appel 的保守合并：只在不会制造新的高危节点时才并。</span></p><p>调试：合并后两个源变量同一寄存器，调试器要靠位置列表——DWARF 后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优拆分 NP 证明。后课默认：拷贝用合并压，压力用拆分泄。下一课表调度：分配前后都可能调度，顺序与拆分交互。</p><p>也不把拆分当多线程 fork。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并消 <code>mov</code>；过并增度数。</li><li>拆分缩短区间，服务调用点与循环。</li><li>迭代合并（George–Appel）是标准工程。</li><li>出处：Chaitin；George and Appel, 1996；对照 Poletto 区间。</li></ul>',7))])}const S=B(d,[["render",c]]);export{u as __pageData,S as default};
